namespace SaturnApp {
public class Settings {
 public string Engine="", Bios=""; public bool Hle=false, Fullscreen=true; public List<string> Folders=new List<string>();
 public void Save(string path) { var x=new XElement("Saturn",new XAttribute("engine",Engine),new XAttribute("bios",Bios),new XAttribute("hle",Hle),new XAttribute("fullscreen",Fullscreen),Folders.Select(f=>new XElement("Folder",f))); var tmp=path+".tmp"; x.Save(tmp); if(File.Exists(path)) File.Replace(tmp,path,path+".bak"); else File.Move(tmp,path); }
 public static Settings Load(string path) {var s=new Settings(); if(!File.Exists(path))return s; var x=XElement.Load(path);s.Engine=(string)x.Attribute("engine")??"";s.Bios=(string)x.Attribute("bios")??"";s.Hle=(bool?)x.Attribute("hle")??false;s.Fullscreen=(bool?)x.Attribute("fullscreen")??true;s.Folders=x.Elements("Folder").Select(e=>e.Value).ToList();return s;}
}
public class Game {public string Path; public string Title {get{return System.IO.Path.GetFileNameWithoutExtension(Path);}}}
public static class Library {
 public static List<Game> Scan(IEnumerable<string> folders,List<string> errors) {var found=new HashSet<string>(StringComparer.OrdinalIgnoreCase);var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);var stack=new Stack<string>(folders);while(stack.Count>0){string dir=stack.Pop();try {dir=System.IO.Path.GetFullPath(dir);if(!seen.Add(dir))continue;if(!Directory.Exists(dir)){errors.Add("Dossier absent : "+dir);continue;}foreach(var f in Directory.GetFiles(dir)){var ext=System.IO.Path.GetExtension(f).ToLowerInvariant();if(ext==".cue"||ext==".iso"||ext==".chd") found.Add(f);}foreach(var d in Directory.GetDirectories(dir))if((File.GetAttributes(d)&FileAttributes.ReparsePoint)==0)stack.Push(d);}catch(Exception e){if(!(e is IOException)&&!(e is UnauthorizedAccessException)&&!(e is ArgumentException))throw;errors.Add(dir+" : "+e.Message);}}return found.Select(f=>new Game{Path=f}).OrderBy(g=>g.Title,StringComparer.CurrentCultureIgnoreCase).ToList();}
 public static void Validate(string path) {if(!File.Exists(path))throw new IOException("Image du jeu introuvable : "+path);if(System.IO.Path.GetExtension(path).Equals(".cue",StringComparison.OrdinalIgnoreCase)){var matches=Regex.Matches(File.ReadAllText(path),"^\\s*FILE\\s+(?:\"([^\"]+)\"|(\\S+))",RegexOptions.Multiline|RegexOptions.IgnoreCase);if(matches.Count==0)throw new IOException("Le fichier CUE ne contient aucune piste FILE.");foreach(Match m in matches){var track=m.Groups[1].Success?m.Groups[1].Value:m.Groups[2].Value;var full=System.IO.Path.GetFullPath(System.IO.Path.Combine(System.IO.Path.GetDirectoryName(path),track));if(!File.Exists(full))throw new IOException("Piste manquante : "+track+"\nConservez le CUE et ses pistes ensemble.");}}}
}
public static class Engine {
 public static string Quote(string value){if(value.IndexOf('"')>=0||value.IndexOf('\n')>=0||value.IndexOf('\r')>=0)throw new ArgumentException("Chemin invalide.");return "\""+value+"\"";}
 public static string Arguments(Settings s,string game){return "--autostart --iso="+Quote(game)+(s.Hle?" --no-bios":" --bios="+Quote(s.Bios))+(s.Fullscreen?" --fullscreen":"");}
 public static ProcessStartInfo StartInfo(Settings s,string game){if(!File.Exists(s.Engine))throw new IOException("Sélectionnez kronos.exe dans Configuration.");if(!s.Hle&&!File.Exists(s.Bios))throw new IOException("Sélectionnez votre BIOS ou activez explicitement le BIOS émulé.");Library.Validate(game);return new ProcessStartInfo(s.Engine,Arguments(s,game)){UseShellExecute=false,WorkingDirectory=System.IO.Path.GetDirectoryName(s.Engine)};}
}
public class MainForm:Form {
 static readonly Color Base=Color.FromArgb(35,37,33),Panel=Color.FromArgb(48,50,44),Gold=Color.FromArgb(204,182,119),Ink=Color.FromArgb(244,241,231);
 readonly string root=AppDomain.CurrentDomain.BaseDirectory;Settings settings;List<Game> games=new List<Game>();FlowLayoutPanel cards;TextBox search;Label status;Button scan;Process playing;bool scanning;string settingsPath;string data;ToolTip tips=new ToolTip();
 public MainForm(){var iconPath=System.IO.Path.Combine(root,"sakura.ico");if(File.Exists(iconPath))Icon=new Icon(iconPath);Text="Segata Sakura — bibliothèque · Kronos";Size=new Size(1100,760);MinimumSize=new Size(760,560);StartPosition=FormStartPosition.CenterScreen;BackColor=Base;ForeColor=Ink;Font=new Font("Segoe UI",10);AutoScaleMode=AutoScaleMode.Dpi;data=AppPaths.Initialize(root);settingsPath=System.IO.Path.Combine(data,"settings.xml");try{settings=Settings.Load(settingsPath);}catch(Exception e){settings=new Settings();Shown+=(a,b)=>MessageBox.Show(this,"Configuration illisible : "+e.Message+"\nLe fichier existant est conservé jusqu'à votre prochain enregistrement.");}var portable=System.IO.Path.Combine(root,"engine","kronos.exe");if(File.Exists(portable))settings.Engine=portable;
 var shell=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=4,Margin=Padding.Empty,Padding=Padding.Empty};shell.RowStyles.Add(new RowStyle(SizeType.Absolute,104));shell.RowStyles.Add(new RowStyle(SizeType.Absolute,100));shell.RowStyles.Add(new RowStyle(SizeType.Percent,100));shell.RowStyles.Add(new RowStyle(SizeType.Absolute,34));Controls.Add(shell);
 var header=new System.Windows.Forms.Panel{Dock=DockStyle.Fill,BackColor=Gold,Margin=Padding.Empty};shell.Controls.Add(header,0,0);var logo=new PictureBox{Location=new Point(22,12),Size=new Size(70,78),SizeMode=PictureBoxSizeMode.Zoom};var logoPath=System.IO.Path.Combine(root,"sakura-logo.png");if(File.Exists(logoPath))logo.Image=Image.FromFile(logoPath);header.Controls.Add(logo);header.Controls.Add(new Label{Text="SEGATA SAKURA",Font=new Font("Georgia",27),ForeColor=Base,Location=new Point(108,15),AutoSize=true});header.Controls.Add(new Label{Text="VOTRE COLLECTION · VOTRE UNIVERS",ForeColor=Base,Location=new Point(111,65),AutoSize=true,Font=new Font("Segoe UI",9)});
 var config=Button("Configuration",(a,b)=>Configure());config.Anchor=AnchorStyles.Right|AnchorStyles.Top;config.Location=new Point(870,30);header.Controls.Add(config);header.Resize+=(a,b)=>config.Left=header.Width-config.Width-24;
 var bar=new FlowLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(18,10,12,5),WrapContents=true,Margin=Padding.Empty};shell.Controls.Add(bar,0,1);bar.Controls.Add(Button("Ouvrir un jeu…",(a,b)=>OpenGame()));bar.Controls.Add(Button("+ Dossier",(a,b)=>AddFolder()));scan=Button("Actualiser",(a,b)=>Scan());bar.Controls.Add(scan);search=new TextBox{Width=200,Margin=new Padding(16,7,8,0),BackColor=Panel,ForeColor=Ink,BorderStyle=BorderStyle.FixedSingle};search.AccessibleName="Rechercher un jeu";tips.SetToolTip(search,"Rechercher dans la bibliothèque");search.TextChanged+=(a,b)=>RenderGames();bar.Controls.Add(new Label{Text="Rechercher",AutoSize=true,Margin=new Padding(12,8,0,0)});bar.Controls.Add(search);
 cards=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true,Padding=new Padding(18),BackColor=Base,Margin=Padding.Empty};shell.Controls.Add(cards,0,2);status=new Label{Dock=DockStyle.Fill,Text="Kronos · prêt à configurer",Padding=new Padding(20,6,0,0),BackColor=Panel,Font=new Font("Segoe UI",9)};shell.Controls.Add(status,0,3);Shown+=(a,b)=>Scan();FormClosing+=(a,b)=>{if(playing!=null&&!playing.HasExited)MessageBox.Show(this,"La partie reste ouverte dans Kronos.","Segata Sakura");};}
 Button Button(string title,EventHandler action){var b=new Button{Text=title,AutoSize=true,Height=36,MinimumSize=new Size(100,36),FlatStyle=FlatStyle.Flat,BackColor=Panel,ForeColor=Ink,Padding=new Padding(8,2,8,2),Margin=new Padding(4)};b.FlatAppearance.BorderColor=Color.FromArgb(90,92,78);b.Click+=action;return b;}
 void Error(Exception e){status.Text="Action interrompue";MessageBox.Show(this,e.Message,"Segata Sakura",MessageBoxButtons.OK,MessageBoxIcon.Warning);}
 void AddFolder(){try{var folder=FolderPicker.Choose(this);if(folder==null)return;if(!settings.Folders.Contains(folder,StringComparer.OrdinalIgnoreCase))settings.Folders.Add(folder);settings.Save(settingsPath);Scan();}catch(Exception e){Error(e);}}
 void OpenGame(){using(var d=new OpenFileDialog{Title="Choisir un jeu Saturn",Filter="Jeux Saturn|*.cue;*.iso;*.chd",CheckFileExists=true,Multiselect=false})if(d.ShowDialog(this)==DialogResult.OK){var game=new Game{Path=d.FileName};try{Library.Validate(game.Path);var folder=System.IO.Path.GetDirectoryName(game.Path);if(!settings.Folders.Contains(folder,StringComparer.OrdinalIgnoreCase)){settings.Folders.Add(folder);settings.Save(settingsPath);Scan();}if(!settings.Hle&&!File.Exists(settings.Bios)){MessageBox.Show(this,"Choisissez votre BIOS Saturn dans Configuration pour commencer.","Premier lancement");Configure();if(!settings.Hle&&!File.Exists(settings.Bios))return;}Launch(game);}catch(Exception e){Error(e);}}}
 async void Scan(){if(scanning)return;scanning=true;scan.Enabled=false;status.Text="Recherche des jeux…";var errors=new List<string>();var dirs=settings.Folders.ToArray();try{games=await Task.Run(()=>Library.Scan(dirs,errors));RenderGames();status.Text=games.Count+" image(s) de disque · "+(errors.Count==0?"Bibliothèque actualisée":errors.Count+" dossier(s) non lu(s)");if(errors.Count>0){File.WriteAllLines(System.IO.Path.Combine(data,"scan-errors.txt"),errors);tips.SetToolTip(status,string.Join("\n",errors.Take(4)));}}catch(Exception e){Error(e);}finally{scanning=false;scan.Enabled=true;}}
 void RenderGames(){cards.SuspendLayout();foreach(Control c in cards.Controls.Cast<Control>().ToArray()){cards.Controls.Remove(c);c.Dispose();}var list=games.Where(g=>g.Title.IndexOf(search.Text,StringComparison.CurrentCultureIgnoreCase)>=0).ToList();if(list.Count==0){var empty=new Label{Text=games.Count==0?"Votre première partie commence ici.\n\nAjoutez un dossier contenant vos jeux Saturn.\nFormats : CUE + pistes, ISO, CHD.\n\nLes jeux et le BIOS ne sont pas fournis.":"Aucun jeu ne correspond à votre recherche.",AutoSize=true,Margin=new Padding(20,55,10,20),ForeColor=Ink,Font=new Font("Segoe UI",12)};cards.Controls.Add(empty);}foreach(var game in list){var item=new System.Windows.Forms.Panel{Size=new Size(220,322),Margin=new Padding(8),BackColor=Panel};var stripe=new Label{Text="S A T U R N",Dock=DockStyle.Top,Height=26,BackColor=Gold,ForeColor=Base,TextAlign=ContentAlignment.MiddleCenter,Font=new Font("Georgia",10)};item.Controls.Add(stripe);var pic=new PictureBox{Location=new Point(12,37),Size=new Size(196,172),SizeMode=PictureBoxSizeMode.Zoom,BackColor=Base};var cover=CoverPath(game);if(File.Exists(cover)){try{using(var im=Image.FromFile(cover))pic.Image=new Bitmap(im);}catch{}}pic.Disposed+=(a,b)=>{if(pic.Image!=null)pic.Image.Dispose();};if(pic.Image==null)pic.Paint+=(a,b)=>{using(var pen=new Pen(Gold,2)){b.Graphics.DrawEllipse(pen,61,46,74,74);b.Graphics.DrawEllipse(pen,91,76,14,14);} };item.Controls.Add(pic);var title=new Label{Text=game.Title,Location=new Point(12,219),Size=new Size(196,48),AutoEllipsis=true};tips.SetToolTip(title,game.Path);item.Controls.Add(title);var play=Button("▶ Jouer",(a,b)=>Launch(game));play.Location=new Point(9,275);play.BackColor=Gold;play.ForeColor=Base;item.Controls.Add(play);var art=Button("Jaquette",(a,b)=>SetCover(game));art.MinimumSize=new Size(70,36);art.Location=new Point(118,275);art.Width=90;item.Controls.Add(art);cards.Controls.Add(item);}cards.ResumeLayout();}
 string CoverPath(Game g){using(var sha=System.Security.Cryptography.SHA256.Create()){var hash=BitConverter.ToString(sha.ComputeHash(System.Text.Encoding.UTF8.GetBytes(g.Path.ToUpperInvariant()))).Replace("-","");return System.IO.Path.Combine(data,"covers",hash+".png");}}
 void SetCover(Game g){using(var d=new OpenFileDialog{Filter="Images|*.png;*.jpg;*.jpeg;*.bmp"})if(d.ShowDialog(this)==DialogResult.OK)try{Directory.CreateDirectory(System.IO.Path.Combine(data,"covers"));using(var image=Image.FromFile(d.FileName))image.Save(CoverPath(g),System.Drawing.Imaging.ImageFormat.Png);RenderGames();}catch(Exception e){Error(e);}}
 void Launch(Game g){try{if(playing!=null&&!playing.HasExited){MessageBox.Show(this,"Une session Kronos est déjà ouverte. Fermez-la avant de lancer un autre jeu.");return;}var info=Engine.StartInfo(settings,g.Path);playing=Process.Start(info);status.Text="Kronos lancé · "+g.Title;var timer=new Timer{Interval=1000};timer.Tick+=(a,b)=>{if(playing==null||playing.HasExited){timer.Stop();timer.Dispose();status.Text="Session terminée · retour à la bibliothèque";}};timer.Start();}catch(Exception e){Error(e);}}
 void Configure(){using(var d=new Form{Text="Configuration Segata Sakura",Size=new Size(680,530),MinimumSize=new Size(680,530),StartPosition=FormStartPosition.CenterParent,BackColor=Base,ForeColor=Ink,Font=Font}){var rows=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(20),ColumnCount=3,RowCount=8};rows.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,100));rows.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));rows.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,110));d.Controls.Add(rows);var engine=new TextBox{Text=settings.Engine,Dock=DockStyle.Fill,ReadOnly=true};var bios=new TextBox{Text=settings.Bios,Dock=DockStyle.Fill};rows.Controls.Add(new Label{Text="Kronos",AutoSize=true},0,0);rows.Controls.Add(engine,1,0);rows.Controls.Add(new Label{Text="Moteur inclus",AutoSize=true},2,0);rows.Controls.Add(new Label{Text="BIOS Saturn",AutoSize=true},0,1);rows.Controls.Add(bios,1,1);rows.Controls.Add(Button("Parcourir",(a,b)=>{using(var f=new OpenFileDialog{Filter="BIOS|*.bin;*.rom|Tous les fichiers|*.*"})if(f.ShowDialog(d)==DialogResult.OK)bios.Text=f.FileName;}),2,1);var hle=new CheckBox{Text="Utiliser le BIOS émulé (compatibilité variable)",Checked=settings.Hle,AutoSize=true};rows.Controls.Add(hle,1,2);rows.SetColumnSpan(hle,2);var full=new CheckBox{Text="Démarrer les jeux en plein écran",Checked=settings.Fullscreen,AutoSize=true};rows.Controls.Add(full,1,3);rows.SetColumnSpan(full,2);var folders=new ListBox{Dock=DockStyle.Fill,Height=95,BackColor=Panel,ForeColor=Ink};folders.Items.AddRange(settings.Folders.ToArray());rows.Controls.Add(new Label{Text="Dossiers",AutoSize=true},0,4);rows.Controls.Add(folders,1,4);rows.Controls.Add(Button("Retirer",(a,b)=>{if(folders.SelectedIndex>=0)folders.Items.RemoveAt(folders.SelectedIndex);}),2,4);var advanced=Button("Ouvrir les réglages de Kronos",(a,b)=>{try{if(playing!=null&&!playing.HasExited)throw new IOException("Fermez la session en cours avant d'ouvrir une autre instance.");if(!File.Exists(engine.Text))throw new IOException("Sélectionnez kronos.exe.");playing=Process.Start(new ProcessStartInfo(engine.Text){WorkingDirectory=System.IO.Path.GetDirectoryName(engine.Text),UseShellExecute=false});}catch(Exception e){Error(e);}});rows.Controls.Add(advanced,1,5);rows.SetColumnSpan(advanced,2);rows.Controls.Add(new Label{Text="Manette, vidéo et sauvegardes : réglages natifs de Kronos.\nLe jeu s'ouvre dans sa propre fenêtre.",AutoSize=true},1,6);rows.SetColumnSpan(rows.GetControlFromPosition(1,6),2);var save=Button("Enregistrer",(a,b)=>{try{if(!File.Exists(engine.Text))throw new IOException("kronos.exe est introuvable.");if(!hle.Checked&&!File.Exists(bios.Text))throw new IOException("Choisissez un BIOS ou cochez le BIOS émulé.");var next=new Settings{Engine=System.IO.Path.GetFullPath(engine.Text),Bios=bios.Text,Hle=hle.Checked,Fullscreen=full.Checked,Folders=folders.Items.Cast<string>().ToList()};next.Save(settingsPath);settings=next;d.DialogResult=DialogResult.OK;}catch(Exception e){MessageBox.Show(d,e.Message,"Configuration");}});rows.Controls.Add(save,2,7);if(d.ShowDialog(this)==DialogResult.OK)Scan();}}
 public void Snapshot(string path){Show();Application.DoEvents();var deadline=DateTime.UtcNow.AddSeconds(10);while(scanning && DateTime.UtcNow<deadline){Application.DoEvents();System.Threading.Thread.Sleep(10);}Application.DoEvents();using(var bmp=new Bitmap(Width,Height)){DrawToBitmap(bmp,new Rectangle(0,0,Width,Height));bmp.Save(path);}Close();}
