static class Program {
 [STAThread]static int Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);if(args.Length>0&&args[0]=="--self-test")return Tests.Run();if(args.Length==2&&args[0]=="--screenshot"){using(var f=new MainForm())f.Snapshot(args[1]);return 0;}Application.Run(new MainForm());return 0;}
}
static class Tests {
 public static int Run(){var dir=System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"test-fixtures-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);var report=new List<string>();try{var bin=System.IO.Path.Combine(dir,"épisode 1.bin");File.WriteAllText(bin,"fixture");var cue=System.IO.Path.Combine(dir,"Sakura test.cue");File.WriteAllText(cue,"FILE \"épisode 1.bin\" BINARY\n TRACK 01 MODE1/2352\n INDEX 01 00:00:00");Library.Validate(cue);report.Add("PASS CUE avec accents et espaces");var errors=new List<string>();var games=Library.Scan(new[]{dir,dir},errors);if(games.Count!=1||errors.Count!=0)throw new Exception("Scan incorrect");report.Add("PASS scan sans doublons ni pistes BIN isolées");File.Delete(bin);bool failed=false;try{Library.Validate(cue);}catch(IOException){failed=true;}if(!failed)throw new Exception("Piste manquante ignorée");report.Add("PASS piste CUE manquante détectée");var s=new Settings{Engine="C:\\Moteur Saturn\\kronos.exe",Bios="C:\\BIOS\\été.bin",Fullscreen=true};s.Folders.Add(dir);var config=System.IO.Path.Combine(dir,"settings.xml");s.Save(config);s.Save(config);var loaded=Settings.Load(config);if(loaded.Bios!=s.Bios||loaded.Folders.Count!=1)throw new Exception("Persistence");report.Add("PASS sauvegarde et relecture configuration");var a=Engine.Arguments(s,cue);if(!a.Contains("--iso=\""+cue+"\"")||!a.Contains("--bios=\""+s.Bios+"\""))throw new Exception("Arguments");s.Hle=true;if(Engine.Arguments(s,cue).Contains("--bios="))throw new Exception("HLE");report.Add("PASS arguments Kronos BIOS et HLE");Library.Scan(new[]{System.IO.Path.Combine(dir,"missing")},errors);if(errors.Count!=1)throw new Exception("Dossier absent");report.Add("PASS dossier absent signalé");File.WriteAllLines(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"test-results.txt"),report);return 0;}catch(Exception e){report.Add("FAIL "+e);File.WriteAllLines(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"test-results.txt"),report);return 1;}finally{Directory.Delete(dir,true);}}
}
